export function buildContentScriptRegistration(sites: string[]) {
  return {
    id: CONTENT_SCRIPT_ID,
    js: ['content-scripts/video-hotkeys.js'],
    css: ['content-scripts/video-hotkeys.css'],
    matches: sites.map(domain => `*://*.${domain}/*`),
    allFrames: true,
    matchOriginAsFallback: true,
    runAt: 'document_idle' as const,
  };
}

export function getActiveVideo(): HTMLVideoElement | null {
  const videos = findAllVideos(document);
  if (videos.length === 0) return null;

  const playing = videos.find(v => !v.paused && !v.ended);
  if (playing) return playing;

  return videos.reduce((prev, curr) =>
    curr.offsetWidth * curr.offsetHeight > prev.offsetWidth * prev.offsetHeight ? curr : prev
  );
}

